@echasnovski `oil.nvim` doesn't have such issue.

init.lua with `oil.nvim`:

```lua
vim.g.mapleader = ' '

local root = vim.fn.fnamemodify('./.repro', ':p')

-- set stdpaths to use .repro
for _, name in ipairs({ 'config', 'data', 'state', 'cache' }) do
  vim.env[('XDG_%s_HOME'):format(name:upper())] = root .. '/' .. name
end

-- bootstrap lazy
local lazypath = root .. '/plugins/lazy.nvim'
if not vim.loop.fs_stat(lazypath) then
  vim.fn.system({
    'git',
    'clone',
    '--filter=blob:none',
    '--single-branch',
    'https://github.com/folke/lazy.nvim.git',
    lazypath,
  })
end
vim.opt.runtimepath:prepend(lazypath)

-- install plugins
local plugins = {
  { 'nvim-lua/plenary.nvim' },
  { 'stevearc/dressing.nvim', opts = {} },
  {
    'stevearc/oil.nvim',
    opts = {
      default_file_explorer = true,
      keymaps = {
        ["g?"] = "actions.show_help",
        ["<CR>"] = "actions.select",
        ["<C-v>"] = "actions.select_vsplit",
        ["<C-x>"] = "actions.select_split",
        ["<C-t>"] = "actions.select_tab",
        ["<C-p>"] = "actions.preview",
        ["<C-c>"] = "actions.close",
        ["<C-r>"] = "actions.refresh",
        ["y"] = "actions.copy_entry_path",
        ["-"] = "actions.parent",
        ["`"] = "actions.cd",
        ["~"] = "actions.tcd",
        ["g."] = "actions.toggle_hidden",
      },
      use_default_keymaps = false,
      float = {
        padding = 3,
        border = 'single',
        win_options = {
          winblend = 0,
        }
      }
    },
    keys = {
      {
        '-',
        function()
          require('oil').open()
        end,
        desc = 'Open oil file browser(buf)',
      },
    },
  },
  {
    --- some issues
    --- https://github.com/nvim-treesitter/nvim-treesitter/issues/3970#issuecomment-1353836834
    --- https://github.com/nvim-treesitter/nvim-treesitter/issues/2014#issuecomment-970342040
    --- `:echo nvim_get_runtime_file('*/python.so', v:true)`
    'nvim-treesitter/nvim-treesitter',
    build = function()
      if #vim.api.nvim_list_uis() == 0 then
        -- update sync if running headless
        vim.cmd.TSUpdateSync()
      else
        -- otherwise update async
        vim.cmd.TSUpdate()
      end
    end,
    lazy = true,
    event = { 'BufReadPost', 'BufNewFile' },
    -- event = 'VeryLazy',
    keys = {
      -- { "<Enter>",    desc = "Init Increment selection" },
      -- { "<Enter>",    desc = "node node incremental selection",      mode = "x" },
      { "<BS>", desc = "Decrement selection", mode = "x" },
      { '<leader>cr', desc = 'Smart rename/nvim-treesitter-refactor' },
    },
    dependencies = {
    },
    init = function()
      vim.opt.smartindent = false
    end,
    config = function()
      require('nvim-treesitter.install').prefer_git = true
      require('nvim-treesitter.configs').setup({
        -- parser_install_dir = parser_install_dir,
        ensure_installed = { 'python' }, -- one of "all", or a list of languages
        sync_install = true, -- install languages synchronously (only applied to `ensure_installed`)
        auto_install = true,
        ignore_install = {}, -- list of parsers to ignore installing
      })
    end,
  },
  {
    "nvim-treesitter/nvim-treesitter-context",
    event = "BufReadPre",
    lazy = true,
    enabled = true,
    opts = {
      max_lines = 3,
      mode = "cursor",
      min_window_height = 5,
    },
    keys = {
      {
        '[c', '<cmd>lua require("treesitter-context").go_to_context()<cr>', desc = 'Treesitter Context: Go to context'
      }
    },
    config = function(_, opts)
      require('treesitter-context').setup(opts)
      vim.cmd([[hi TreesitterContextBottom gui=underline guisp=Grey]])
    end
  },
  -- add any other pugins here
}

require('lazy').setup({
  spec = plugins,
  root = root .. '/plugins',
  defaults = {
    lazy = false,
  },
  state = root .. '/lazy/state.json',
  performance = {
    cache = {
      enabled = false,
    }
  }
})

-- add anything else here
vim.opt.termguicolors = true
vim.cmd([[colorscheme default]])
```
